 loot=loot.filter(l=>{l.life-=dt;if(hyp(l,p)<30){if(l.type==='scrap'){scrap++;p.hp=Math.min(100,p.hp+3);say('SCRAP RECOVERED · +3 VITALS')}else{reserve+=12;say('CARTRIDGES RECOVERED · +12')}return false}return l.life>0});bits=bits.filter(b=>{b.life-=dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.vx*=.96;b.vy*=.96;return b.life>0});$('#prompt').textContent=loot.some(l=>hyp(l,p)<30)?'E · SCAVENGE':'SPACE · BOILER DASH';updateHud()}
function spawnEnemy(){let a=rand(0,7),r=rand(Math.max(W,H)*.65,Math.max(W,H)*.85),elite=wave>=3&&Math.random()<.26;enemies.push({x:p.x+Math.cos(a)*r,y:p.y+Math.sin(a)*r,hp:elite?4:2,r:elite?21:17,speed:elite?51:rand(38,51),damage:elite?15:9,attack:rand(.3,1.2),elite,flash:0,dead:false})}
function fire(){if(shot>0||reloading)return;if(ammo<=0){reloadGun();return}ammo--;shot=.19;let a=p.angle+rand(-.035,.035);bullets.push({x:p.x+Math.cos(a)*22,y:p.y+Math.sin(a)*22,vx:Math.cos(a)*680,vy:Math.sin(a)*680,life:.65});burst(p.x+Math.cos(a)*29,p.y+Math.sin(a)*29,'#ffc969',3);updateHud()}
function reloadGun(){if(!reloading&&ammo<12&&reserve>0){reloading=true;reloadTimer=58;say('RELOADING COIL CARBINE…')}}function burst(x,y,color,n=6){for(let i=0;i<n;i++){let a=rand(0,7),v=rand(30,150);bits.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.12,.45),max:.45,color})}}
function updateHud(){if(!p)return;$('#hp').style.width=clamp(p.hp,0,100)+'%';$('#hpv').textContent=Math.ceil(p.hp)+' / 100';$('#st').style.width=p.st+'%';$('#stv').textContent=Math.ceil(p.st)+'%';$('#ammo').textContent=ammo;$('#reserve').textContent=reserve;$('#wave').textContent=String(wave).padStart(2,'0');$('#clock').textContent=String(Math.floor(time/60)).padStart(2,'0')+':'+String(Math.floor(time%60)).padStart(2,'0')}
function finish(win){if(done)return;done=true;active=false;document.exitPointerLock?.();$('#endey').textContent=win?'FIELD REPORT · ENGINE SECURED':'FIELD REPORT · SIGNAL LOST';$('#endtitle').textContent=win?'THE ENGINE HOLDS.':'THE FOG TAKES ALL.';$('#endcopy').innerHTML=win?`You kept the last relay alive through the fog.<br><br><b>${kills}</b> clockwork horrors dismantled · <b>${scrap}</b> scrap recovered · ${Math.floor(time)} seconds survived.<br><br>The brass heart beats on. For tonight, the wasteland is quiet.`:`The relay fell silent after ${Math.floor(time)} seconds.<br><br><b>${kills}</b> horrors dismantled · <b>${scrap}</b> scrap recovered.<br><br>The engine still waits for a better engineer.`;$('#end').classList.remove('hidden')}

function draw(){g.clearRect(0,0,W,H);g.fillStyle='#24281f';g.fillRect(0,0,W,H);let t=70,ox=((W/2-p.x)%t+t)%t,oy=((H/2-p.y)%t+t)%t;g.strokeStyle='#313329';g.lineWidth=1;for(let x=ox-t;x<W+t;x+=t){g.beginPath();g.moveTo(x,0);g.lineTo(x,H);g.stroke()}for(let y=oy-t;y<H+t;y+=t){g.beginPath();g.moveTo(0,y);g.lineTo(W,y);g.stroke()}scenery.forEach(d=>{let q=screen(d.x,d.y);if(q.x>-80&&q.x<W+80&&q.y>-80&&q.y<H+80)drawScenery(q.x,q.y,d)});let q=screen(430,-90);drawRelay(q.x,q.y);loot.forEach(l=>{let q=screen(l.x,l.y);g.save();g.translate(q.x,q.y);g.rotate(time*1.5);g.fillStyle=l.type==='ammo'?'#d9b255':'#8daa72';g.shadowColor=g.fillStyle;g.shadowBlur=11;g.fillRect(-7,-7,14,14);g.restore()});bullets.forEach(b=>{let q=screen(b.x,b.y);g.strokeStyle='#ffd377';g.lineWidth=3;g.shadowBlur=10;g.shadowColor='#eda64b';g.beginPath();g.moveTo(q.x,q.y);g.lineTo(q.x-b.vx*.028,q.y-b.vy*.028);g.stroke();g.shadowBlur=0});enemies.forEach(drawEnemy);bits.forEach(b=>{let q=screen(b.x,b.y);g.globalAlpha=Math.max(0,b.life/b.max);g.fillStyle=b.color;g.beginPath();g.arc(q.x,q.y,2.4,0,7);g.fill();g.globalAlpha=1});drawPlayer();let fog=g.createRadialGradient(W/2,H/2,80,W/2,H/2,Math.max(W,H)*.72);fog.addColorStop(0,'#181c1500');fog.addColorStop(.68,'#0a100e2e');fog.addColorStop(1,'#080f0eaa');g.fillStyle=fog;g.fillRect(0,0,W,H)}
function drawScenery(x,y,d){g.save();g.translate(x,y);g.rotate(d.r);g.globalAlpha=.7;if(d.kind<.2){g.fillStyle='#493e2b';g.beginPath();g.ellipse(0,0,22*d.s,10*d.s,-.5,0,7);g.fill();g.strokeStyle='#75623d';g.lineWidth=2;g.stroke()}else if(d.kind<.35){g.strokeStyle='#66704b';g.lineWidth=3;g.beginPath();g.moveTo(0,14);g.lineTo(-2,-8);g.lineTo(-10,-19);g.moveTo(-2,-7);g.lineTo(9,-17);g.stroke();g.fillStyle='#66704b';g.beginPath();g.arc(-10,-19,5,0,7);g.arc(9,-17,5,0,7);g.fill()}else if(d.kind<.46){g.fillStyle='#725b39';g.fillRect(-18,-12,36,24);g.fillStyle='#a1804b';g.fillRect(-16,-9,32,3);g.strokeStyle='#312b20';g.lineWidth=2;g.strokeRect(-18,-12,36,24)}else{g.fillStyle='#34372c';g.beginPath();g.ellipse(0,0,11*d.s,6*d.s,.2,0,7);g.fill()}g.restore()}
function drawRelay(x,y){g.save();g.translate(x,y);g.shadowBlur=20;g.shadowColor=relay?'#a1bd69':'#b28b43';g.fillStyle='#151b18';g.strokeStyle=relay?'#a8c277':'#b38b4e';g.lineWidth=3;g.beginPath();g.arc(0,0,45,0,7);g.fill();g.stroke();g.rotate(time*.2);g.strokeStyle='#c09a53';g.lineWidth=3;g.beginPath();g.arc(0,0,30,0,5.1);g.stroke();g.rotate(-time*.4);g.strokeStyle='#b8ad86';g.beginPath();g.arc(0,0,20,0,5);g.stroke();g.shadowBlur=0;g.fillStyle=relay?'#bacd79':'#d99b42';g.beginPath();g.arc(0,0,8,0,7);g.fill();g.fillStyle='#e3d6af';g.font='10px DM Mono';g.textAlign='center';g.fillText('RELAY',0,-57);if(relayHold>0&&!relay){g.strokeStyle='#ead17c';g.beginPath();g.arc(0,0,53,-Math.PI/2,-Math.PI/2+Math.min(1,relayHold/1.3)*Math.PI*2);g.stroke()}g.restore()}
function drawEnemy(e){let q=screen(e.x,e.y);if(q.x< -70||q.x>W+70||q.y< -70||q.y>H+70)return;g.save();g.translate(q.x,q.y);g.rotate(Math.atan2(p.y-e.y,p.x-e.x));g.shadowColor=e.elite?'#d18b4d':'#773f33';g.shadowBlur=14;g.fillStyle=e.flash?'#f0c77b':e.elite?'#755842':'#554638';g.strokeStyle=e.elite?'#d19a4d':'#9e6044';g.lineWidth=2;g.beginPath();g.ellipse(0,0,e.r,e.r*.78,0,0,7);g.fill();g.stroke();g.shadowBlur=0;g.fillStyle='#221d19';g.fillRect(-4,-7,e.r*.7,6);g.fillStyle=e.flash?'#fff0aa':'#ef9b55';g.fillRect(e.r*.2,-6,5,4);g.fillStyle='#977343';g.fillRect(-e.r*.5,-e.r*.9,7,5);g.fillRect(-e.r*.5,e.r*.7,7,5);if(e.elite){g.strokeStyle='#bd974f';g.beginPath();g.arc(0,0,e.r+5,0,7);g.stroke()}g.restore()}
function drawPlayer(){g.save();g.translate(W/2,H/2);g.rotate(p.angle);g.globalAlpha=p.inv>0&&Math.floor(time*18)%2===0?.35:1;g.shadowColor='#d6a652';g.shadowBlur=13;g.fillStyle='#353b31';g.strokeStyle='#b4975b';g.lineWidth=2;g.beginPath();g.ellipse(0,0,17,14,0,0,7);g.fill();g.stroke();g.fillStyle='#806644';g.fillRect(0,-5,24,10);g.fillStyle='#ccb56d';g.fillRect(9,-2,19,4);g.fillStyle='#242923';g.beginPath();g.arc(-2,0,7,0,7);g.fill();g.strokeStyle='#a37d43';g.beginPath();g.arc(-2,0,9,0,5.4);g.stroke();g.shadowBlur=0;g.fillStyle='#dca352';g.fillRect(2,-3,3,6);g.restore()}
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR')reloadGun();if(e.code==='Escape'&&active){paused=!paused;$('#pause').classList.toggle('hidden',!paused);if(paused)document.exitPointerLock?.();else{last=performance.now();c.requestPointerLock?.();requestAnimationFrame(frame)}}});addEventListener('keyup',e=>keys[e.code]=false);c.addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY});c.addEventListener('mousedown',e=>{if(e.button===0){mouse.down=true;c.requestPointerLock?.()}});addEventListener('mouseup',()=>mouse.down=false);c.addEventListener('contextmenu',e=>e.preventDefault());$('#go').onclick=start;$('#again').onclick=start;$('#resume').onclick=()=>{paused=false;$('#pause').classList.add('hidden');last=performance.now();requestAnimationFrame(frame);c.requestPointerLock?.()};
let stick=$('#stick'),stickId;stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);stickMove(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stickMove(e)});stick.addEventListener('pointerup',e=>{if(e.pointerId===stickId){stickId=null;move={x:0,y:0}}});function stickMove(e){let r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/(r.width*.34),y=(e.clientY-r.top-r.height/2)/(r.height*.34),m=Math.hypot(x,y);if(m>1){x/=m;y/=m}move={x,y}}function hold(id,on,off){let b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);on()});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,off))}hold('#fire',()=>fireTouch=true,()=>fireTouch=false);hold('#dash',()=>dashTouch=true,()=>dashTouch=false);$('#reload').addEventListener('pointerdown',e=>{e.preventDefault();reloadGun()});c.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'){mouse.x=e.clientX;mouse.y=e.clientY;fireTouch=true}});c.addEventListener('pointermove',e=>{if(e.pointerType==='touch'&&fireTouch){mouse.x=e.clientX;mouse.y=e.clientY}});c.addEventListener('pointerup',e=>{if(e.pointerType==='touch')fireTouch=false});init();draw();
